      const gap = this.selectedAllocationGap();
      const max = this.selectedAllocationMax();
      const amount = Math.max(0, Math.min(this.cashAllocateAmount ?? 0, max));
      if (!this.selectedAccount) {
        return;
      }
      const effectiveAmount = this.cashAllocateType === 'protection' && gap <= this.statusEps ? 0 : amount;
      this.dashboardService.saveCashAllocation({
        account: this.selectedAccount,
        ticker: this.cashAllocateTicker,
        type: this.cashAllocateType,
        amount: effectiveAmount
      }).subscribe({
        next: saved => {
          const idx = this.cashAllocations.findIndex(item => item.ticker === saved.ticker && item.type === saved.type);
          if (idx >= 0) {
            this.cashAllocations[idx] = saved;
          } else {
            this.cashAllocations.push(saved);
          }
          if (saved.amount <= 0) {
            this.cashAllocations = this.cashAllocations.filter(item => !(item.ticker === saved.ticker && item.type === saved.type));
