    normalizeProtectionAllocations(rows) {
      if (!rows.length || !this.selectedAccount || !this.stockRows.length) {
        return rows;
      }
      const updates = [];
      const normalized = rows.map(item => {
        if (item.type !== 'protection') {
          return item;
        }
        const row = this.stockRows.find(stock => stock.ticker === item.ticker);
        if (!row) {
          return item;
        }
        const gap = this.stockProtectionGap(row);
        const current = item.amount ?? 0;
        const clamped = Math.max(0, Math.min(current, gap));
        if (Math.abs(clamped - current) > this.statusEps) {
          const updated = {
            ...item,
            amount: clamped
          };
          updates.push(updated);
          return updated;
        }
        return item;
      });
      updates.forEach(item => {
        this.dashboardService.saveCashAllocation({
          account: this.selectedAccount,
          ticker: item.ticker,
          type: item.type,
          amount: item.amount ?? 0
        }).subscribe({
          next: saved => {
            const idx = this.cashAllocations.findIndex(entry => entry.ticker === saved.ticker && entry.type === saved.type);
            if (idx >= 0) {
              if (saved.amount <= 0) {
                this.cashAllocations.splice(idx, 1);
